python3 -c '
import json, subprocess, os

def run_tool(tn, ar):
    cmd = ["mcp-tool", "call", "google-cloud", tn, json.dumps(ar)]
    r = subprocess.run(cmd, capture_output=True, text=True, stderr=subprocess.DEVNULL)
    return r.stdout

def parse_bq(o):
    for line in reversed(o.strip().split(chr(10))):
        s = line.strip()
        if s.startswith("{"):
            return json.loads(s)
    return None

o = run_tool("bigquery_run_query", {"query": "SELECT student_id, AVG(score) as avg_score FROM (SELECT student_id, score FROM mcp-bench0606.academic_warning.scores_2501 UNION ALL SELECT student_id, score FROM mcp-bench0606.academic_warning.scores_2502 UNION ALL SELECT student_id, score FROM mcp-bench0606.academic_warning.scores_2503 UNION ALL SELECT student_id, score FROM mcp-bench0606.academic_warning.scores_2504 UNION ALL SELECT student_id, score FROM mcp-bench0606.academic_warning.scores_2505 UNION ALL SELECT student_id, score FROM mcp-bench0606.academic_warning.scores_2506 UNION ALL SELECT student_id, score FROM mcp-bench0606.academic_warning.scores_2507) GROUP BY student_id ORDER BY student_id"})
hr = parse_bq(o)
print("Historical rows:", len(hr["rows"]))

import csv
latest = {}
with open("/app/latest_quiz_scores.csv") as f:
    for row in csv.DictReader(f):
        latest[row["student_id"]] = (row["name"], float(row["score"]))
print("Latest:", len(latest))
ha = {r["student_id"]: r["avg_score"] for r in hr["rows"]}

bs = []
cs = []
for sid in sorted(latest.keys()):
    nm, sc = latest[sid]
    if sid not in ha:
        continue
    a = ha[sid]
    dp = (a - sc) / a * 100
    if dp > 25:
        bs.append((sid, nm, sc, round(a,2), round(dp,2)))
        if dp > 45:
            cs.append((sid, nm, sc, round(a,2), round(dp,2)))

print(">25%:", len(bs))
print(">45%:", len(cs))

with open("/app/bad_student.csv", "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["student_id","name","latest_score","historical_avg","drop_percentage"])
    for row in bs:
        w.writerow(row)
print("Wrote bad_student.csv")

for row in cs:
    sid, nm, sc, h, dp = row
    msg = "CRITICAL: Student " + nm + " (ID: " + sid + ") has a " + str(dp) + "% score drop (latest: " + str(sc) + ", historical avg: " + str(h) + ")"
    print("Critical log:", nm, sid)
    le = {"log_name": "academic_warning_critical", "payload": {"level": "CRITICAL", "student_id": sid, "name": nm, "latest_score": sc, "historical_avg": h, "drop_percentage": dp, "message": msg}, "resource_type": "global"}
    lc = {"log_name": "projects/mcp-bench0606/logs/academic_warning_critical", "log_bucket": "exam_log-b711e7743e03", "log_entries": [le]}
    out = run_tool("logging_write_log", lc)
    print("  ", out[:120].strip())

print("Done!")
'

